        if source_kind == "symlink":
            (pack / "linked.md").symlink_to("README.md")
            _write_manifest(pack)
            expected = "E_PACK:SOURCE_TYPE"
        elif source_kind == "hardlink":
            os.link(pack / "README.md", pack / "linked.md")
