def _git(root: Path, *argv: str) -> str:
    return subprocess.run(  # noqa: S603 - fixed absolute Git executable in tmp_path only
        ["/usr/bin/git", "-C", str(root), *argv],
        check=True,
        capture_output=True,
        env={
            "HOME": str(root),
            "LANG": "C.UTF-8",
            "LC_ALL": "C.UTF-8",
            "PATH": "/usr/bin:/bin",
        },
        text=True,
    ).stdout.strip()


