    vector = json.loads(vector_path.read_text())
    cases = vector["counterexamples"]
    target = next(case for case in cases if case["case_id"] == case_id)
    target["expected_error"] = "E_FAKE_ACCEPTED_WITHOUT_PREDICATE"
