    assert browser.is_absolute() and browser.is_file(), "E_BROWSER_UNAVAILABLE"
    result = qualify_chrome_indexeddb_environment(
        tmp_path, browser_binary=browser, transport="pipe"
    )
    assert result["result"] == "PASS", result
