@pytest.mark.parametrize(
    ("damage", "error"),
    [
        ("external-intent", "E_DESTRUCTION_EXTERNAL_ARTIFACT"),
        ("external-proof", "E_DESTRUCTION_EXTERNAL_ARTIFACT"),
        ("external-consumption", "E_DESTRUCTION_EXTERNAL_ARTIFACT"),
        ("setup-error", "E_DESTRUCTION_PROCESS_OUTPUT"),
        ("recovery-error", "E_DESTRUCTION_PROCESS_OUTPUT"),
        ("setup-extra", "E_DESTRUCTION_PROCESS_OUTPUT"),
        ("recovery-extra", "E_DESTRUCTION_PROCESS_OUTPUT"),
        ("reader-before-extra", "E_DESTRUCTION_PROCESS_OUTPUT"),
        ("stderr-missing", "E_DESTRUCTION_PROCESS_STDERR"),
        ("stderr-hash", "E_DESTRUCTION_PROCESS_STDERR"),
        ("stderr-content", "E_DESTRUCTION_PROCESS_STDERR"),
    ],
)
def test_review_virtual_artifact_rejections(
    review_record: dict[str, Any], monkeypatch: pytest.MonkeyPatch, damage: str, error: str
) -> None:
    """Coherent substitutions affect validators without modifying retained evidence."""
    from tools.verify_destruction_evidence import verify_destruction
    from tools.verify_repair_evidence import capture_binding

    row = copy.deepcopy(review_record)
    current = capture_binding()
    if damage.startswith("external-"):
        descriptor = row["artifacts"][damage]
        altered = json.dumps(json.loads(Path(descriptor["path"]).read_bytes()), indent=2).encode()
    elif damage.startswith("stderr-"):
        descriptor = row["processes"][4]["stderr"]
        if damage == "stderr-missing":
            descriptor["path"] += ".missing"
            descriptor["sha256"] = "0" * 64
        elif damage == "stderr-hash":
            descriptor["sha256"] = "0" * 64
        altered = b"unrelated failure on stderr\n"
    else:
        name, alteration = damage.rsplit("-", 1)
        descriptor = next(p for p in row["processes"] if p["name"] == name)["stdout"]
        output = json.loads(Path(descriptor["path"]).read_bytes())
        if alteration == "error":
            output["result"] = {"observed_error": "E_DESTRUCTION_PROOF"}
        else:
            output["observed_error"] = "E_DESTRUCTION_PROOF"
        altered = json.dumps(output).encode()
    path = Path(descriptor["path"])
    if damage not in {"stderr-missing", "stderr-hash"}:

        def rehash(item: Any) -> None:
            if isinstance(item, dict):
                if item.get("path") == str(path):
                    item["sha256"] = hashlib.sha256(altered).hexdigest()
                for child in item.values():
                    rehash(child)
            elif isinstance(item, list):
                for child in item:
                    rehash(child)

        rehash(row)
        read_bytes, read_text = Path.read_bytes, Path.read_text
        monkeypatch.setattr(
            Path, "read_bytes", lambda self: altered if self == path else read_bytes(self)
        )
        monkeypatch.setattr(
            Path,
            "read_text",
            lambda self, *args, **kwargs: (
                altered.decode() if self == path else read_text(self, *args, **kwargs)
            ),
        )
    with pytest.raises(ValueError, match=error):
        verify_destruction(row, current, terminal=False, mutation_type="EXPECTED")"""Environment evidence is real, bounded and never physical-power qualification."""

import copy
import hashlib
import importlib
import json
import shutil
from pathlib import Path
from types import ModuleType, SimpleNamespace
from typing import Any

import pytest


def owner() -> ModuleType:
    try:
        return importlib.import_module("tools.run_environment_qualification")
    except ModuleNotFoundError:
        pytest.fail(
            "environment owner absent: native handles, corruption and browser restart unqualified"
        )


def test_checked_uses_explicit_retained_boundary_without_original_fallback(
    tmp_path: Path,
) -> None:
    from tools.retained_artifact_io import RetainedArtifactIO

    recorded_root = "/mnt/c/Users/thenam/Documents/native-case"
    recorded = recorded_root + "/input.json"
    data = b'{"native":true}'
    closure = tmp_path / "closure"
    (closure / "files").mkdir(parents=True)
    (closure / "files/input.json").write_bytes(data)
    artifacts = RetainedArtifactIO.from_manifest(
        {
            "schema_version": "retained-artifact-manifest/v1",
            "recorded_boundaries": [recorded_root],
            "files": [
                {
                    "recorded_locator": recorded,
                    "recorded_boundary": recorded_root,
                    "copied_relative_path": "files/input.json",
                    "size_bytes": len(data),
                    "sha256": hashlib.sha256(data).hexdigest(),
                }
            ],
        },
        closure,
    )
    descriptor = {
        "path": r"C:\Users\thenam\Documents\native-case\input.json",
        "sha256": hashlib.sha256(data).hexdigest(),
    }
    with pytest.raises(ValueError, match="E_ENV_ARTIFACT_BOUNDARY"):
        owner().checked(descriptor, artifacts=artifacts)
    assert (
        owner().checked(
            descriptor,
            artifacts=artifacts,
            recorded_boundary=r"C:\Users\thenam\Documents\native-case",
        )
        == data
    )


def test_environment_aggregate_dispatches_every_owner_and_keeps_power_hold(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    module = owner()
    seen: list[str] = []
    monkeypatch.setattr(module, "capture_binding", lambda: {"source": "current"})
    for name in (
        "verify_native_storage",
        "verify_filesystem_faults",
        "verify_browser_restart",
        "verify_windows_browser",
    ):
        monkeypatch.setattr(
            module,
            name,
            lambda _report, *, artifacts=None, owner=name: seen.append(owner),
        )
    import tools.run_native_ingestor_qualification as native

    monkeypatch.setattr(
        native,
        "verify_native_ingestor",
        lambda _report, *, artifacts=None: seen.append("native_ingestor"),
    )
    monkeypatch.setattr(
        native,
        "verify_native_commit_io",
        lambda _report, *, artifacts=None: seen.append("native_commit_io"),
    )
    reports = {
        "native": {"cases": []},
        "filesystem": {"faults": [], "commit_io": {"records": []}},
        "linux_browser": {"result": "PASS"},
        "windows_browser": {
            "restart_result": "PASS",
            "result": "HOLD",
            "observed_error": "NO_TARGET",
        },
        "native_ingestor": {"result": "PASS", "cases": []},
        "native_commit_io": {"native_sql06": "PASS"},
    }
    terminal_files = []
    for name, value in reports.items():
        path = tmp_path / f"{name}.json"
        path.write_text(json.dumps(value, sort_keys=True))
        terminal_files.append(
            {"path": str(path), "sha256": hashlib.sha256(path.read_bytes()).hexdigest()}
        )
    report = {
        "result": "PARTIAL_HOLD",
        "binding": {"source": "current"},
        "cases": module._environment_case_projection(reports),
        "reports": reports,
        "scope": "SUPPLEMENTAL_ENVIRONMENT_ONLY",
        "production_authority": "NONE",
        "live_authority": "NONE",
        "money_authority": "NONE",
        "full111": "NOT_RERUN_AT_THIS_SOURCE",
        "security_review": "NOT_REVIEWED",
        "terminal_files": terminal_files,
    }
    module.verify_environment_qualification(report)
    assert set(seen) == {
        "verify_native_storage",
        "verify_filesystem_faults",
        "verify_browser_restart",
        "verify_windows_browser",
        "native_ingestor",
        "native_commit_io",
    }
    # Projection boundary only: the six semantic owners above remain explicit stubs.
    missing_case = copy.deepcopy(report)
    missing_case["cases"].pop()
    with pytest.raises(ValueError, match="^E_ENVIRONMENT_QUALIFICATION$") as missing:
        module.verify_environment_qualification(missing_case)
    assert str(missing.value.__cause__) == "case projection"

    terminal_disagreement = copy.deepcopy(report)
    terminal = Path(terminal_files[0]["path"])
    original = terminal.read_bytes()
    changed = json.dumps({"cases": [], "changed": True}, sort_keys=True).encode()
    terminal.write_bytes(changed)
    terminal_disagreement["terminal_files"][0]["sha256"] = hashlib.sha256(changed).hexdigest()
    try:
        with pytest.raises(ValueError, match="^E_ENVIRONMENT_QUALIFICATION$") as mismatch:
            module.verify_environment_qualification(terminal_disagreement)
        assert str(mismatch.value.__cause__) == "terminal projection"
    finally:
        terminal.write_bytes(original)
    report["result"] = "PASS"
    with pytest.raises(ValueError, match="E_ENVIRONMENT_QUALIFICATION"):
        module.verify_environment_qualification(report)


def test_supplemental_evidence_replays_from_closed_copy_without_originals(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    from tools.run_full_repair_qualification import (
        collect_retained_sources,
        write_closed_inventory,
    )

    module = owner()
    monkeypatch.setattr(module, "capture_binding", lambda: {"source": "current"})
    for name in (
        "verify_native_storage",
        "verify_filesystem_faults",
        "verify_browser_restart",
        "verify_windows_browser",
    ):
        monkeypatch.setattr(module, name, lambda _report, *, artifacts=None: None)
    import tools.run_native_ingestor_qualification as native

    monkeypatch.setattr(native, "verify_native_ingestor", lambda _report, *, artifacts=None: None)
    monkeypatch.setattr(native, "verify_native_commit_io", lambda _report, *, artifacts=None: None)
    workspace = tmp_path / "original"
    workspace.mkdir()
    reports = {
        "native": {"cases": []},
        "filesystem": {"faults": [], "commit_io": {"records": []}},
        "linux_browser": {"result": "PASS"},
        "windows_browser": {
            "restart_result": "PASS",
            "result": "HOLD",
            "observed_error": "NO_TARGET",
        },
        "native_ingestor": {"result": "PASS", "cases": []},
        "native_commit_io": {"native_sql06": "PASS"},
    }
    terminals = []
    for name, value in reports.items():
        path = workspace / f"{name}.json"
        path.write_text(json.dumps(value, sort_keys=True))
        terminals.append(
            {"path": str(path), "sha256": hashlib.sha256(path.read_bytes()).hexdigest()}
        )
    aggregate = workspace / "environment-aggregate.json"
    report = {
        "result": "PARTIAL_HOLD",
        "binding": {"source": "current"},
        "cases": module._environment_case_projection(reports),
        "reports": reports,
        "scope": "SUPPLEMENTAL_ENVIRONMENT_ONLY",
        "production_authority": "NONE",
        "live_authority": "NONE",
        "money_authority": "NONE",
        "full111": "NOT_RERUN_AT_THIS_SOURCE",
        "security_review": "NOT_REVIEWED",
        "terminal_files": terminals,
    }
    aggregate.write_text(json.dumps(report, sort_keys=True))
    inventory = tmp_path / "evidence/inventory.json"
    inventory.parent.mkdir()
    sources = [
        (aggregate, str(aggregate), str(workspace)),
        *collect_retained_sources(
            report, retained_boundaries=(workspace,), live_roots=(Path(__file__).parents[2],)
        ),
    ]
    manifest = write_closed_inventory(sources, inventory)
    qualification = SimpleNamespace(
        environment_qualification_aggregate=aggregate,
        environment_qualification_inventory=inventory,
    )
    config = SimpleNamespace(qualification_evidence=qualification, chrome_path=Path(__file__))
    shutil.rmtree(workspace)

    proof = module.verify_environment_qualification_evidence(aggregate, inventory, config)
    assert proof["result"] == "PARTIAL_HOLD"
    terminal_row = next(
        row for row in manifest["files"] if row["recorded_locator"] == terminals[0]["path"]
    )
    copied = inventory.parent / "retained" / terminal_row["copied_relative_path"]
    copied.write_bytes(b"changed")
    with pytest.raises(ValueError, match="E_ENVIRONMENT_QUALIFICATION"):
        module.verify_environment_qualification_evidence(aggregate, inventory, config)
    report["result"] = "PARTIAL_HOLD"
    report["cases"].append(dict(report["cases"][0]))
    with pytest.raises(ValueError, match="E_ENVIRONMENT_QUALIFICATION"):
        module.verify_environment_qualification(report)


