@pytest.mark.parametrize("change", ["real_flag", "enabled_config", "profile_flag"])
def test_mock_binding_and_key_cannot_create_real_admission(
    tmp_path: Path,
    disabled_live_config: Any,
    fake_clock: Any,
    synthetic_provider_response: Any,
    synthetic_book: Any,
    monkeypatch: pytest.MonkeyPatch,
    change: str,
) -> None:
    service, http, _, _ = make_service(
        tmp_path,
        disabled_live_config,
        fake_clock,
        synthetic_provider_response,
        synthetic_book,
        monkeypatch,
    )
    config, admitted = service.config, service.admitted
    asyncio.run(service.close())
    assert len(admitted.bindings) == 1
    assert admitted.profile.profile_hash == service.admitted.profile.profile_hash
    admitted = replace(admitted, source_kind="OBSERVED_REAL")
    if change == "enabled_config":
        raw = config.public
        raw["enabled"] = True
        config = LiveConfig(raw, config.sha256)
    if change == "profile_flag":
        data = admitted.profile.public
        data.update(status="ACCEPTED", source_kind="OBSERVED_REAL")
        admitted = replace(
            admitted, profile=replace(admitted.profile, _data=data, _real_admitted=True)
        )
    with pytest.raises(ValueError):
        LiveService(config, SecretValue("TEST_ONLY_NOT_A_REAL_KEY"), admitted)
    assert http.paths == []
    assert config.public["model_enabled"] is False and config.public["money_enabled"] is False


def test_direct_live_admission_rejects_intent_url_before_claim(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from types import SimpleNamespace

    from moj_discovery import live_preflight_batched as gate

    config = SimpleNamespace(sha256="TEST_ONLY_CONFIG")
    receipt = SimpleNamespace(
        config=config,
        intent=SimpleNamespace(
            root=gate.ROOT, public={"operator_urls": ["https://miseojeuplus.espacejeux.com/WRONG"]}
        ),
    )
    evidence = SimpleNamespace(
        profile=object(),
        bindings=[
            {
                "provider_fixture_id": 101,
                "operator_match_url": "https://miseojeuplus.espacejeux.com/TEST_ONLY",
            }
        ],
    )
    # This seam isolates URL rejection; external review verification is tested separately.
    monkeypatch.setattr(
        gate, "load_evidence", lambda _config: pytest.fail("full verify after consent")
    )
    checked: list[Any] = []

    def recheck(given_config: Any, given_evidence: Any) -> None:
        assert given_config is config and given_evidence is evidence
        checked.append(given_evidence)

    monkeypatch.setattr(gate, "recheck_live_evidence", recheck)
    monkeypatch.setattr(gate, "verify_receipt", lambda *args: None)
    monkeypatch.setattr(
        gate, "claim_receipt", lambda *args: pytest.fail("mismatched scope claimed")
    )
    with pytest.raises(ValueError, match="E_LIVE_ADMISSION_PENDING"):
        gate.admit_live_run(config, receipt)
    with pytest.raises(ValueError, match="E_LIVE_INTENT_OPERATOR_URL"):
        gate.admit_live_run(config, receipt, verified=evidence)
    assert checked == [evidence]import copy
import io
import json
from pathlib import Path
from typing import Any
from uuid import uuid4

import pytest

from moj_discovery.provider_protocol import ProviderScope
from moj_discovery.providers.api_football import ApiFootballClient, ProviderError
from moj_discovery.providers.quota import QuotaLedger
from moj_discovery.secrets_local import SecretValue

QUOTA = {
    "x-ratelimit-requests-limit": "7500",
    "x-ratelimit-requests-remaining": "7499",
    "x-ratelimit-limit": "300",
    "x-ratelimit-remaining": "299",
}
STATUS = {
    "errors": [],
    "results": 1,
    "paging": {"current": 1, "total": 1},
    "response": {
        "account": {"email": "PRIVATE_NOT_RETAINED"},
        "subscription": {"plan": "Pro", "active": True, "end": "2026-12-31"},
        "requests": {"current": 1, "limit_day": 7500},
    },
}


class Reply(io.BytesIO):
    def __init__(self, body: Any, status: Any = 200, headers: Any = None, url: Any = None) -> None:
        super().__init__(body if isinstance(body, bytes) else json.dumps(body).encode())
        self.status = status
        self.headers = {**QUOTA, **(headers or {})}
        self.url = url

    def geturl(self) -> Any:
        return self.url


class MockHTTP:
    def __init__(self, replies: Any) -> None:
        self.replies = list(replies)
        self.calls: list[Any] = []

    def open(self, request: Any, timeout: Any) -> Any:
        self.calls.append((request, timeout))
        result = self.replies.pop(0)
        if isinstance(result, BaseException):
            raise result
        if result.url is None:
            result.url = request.full_url
        return result


def make_client(tmp_path: Any, clock: Any, replies: Any, **scope_values: Any) -> Any:
    ids = scope_values.pop("fixture_ids", (101, 103))
    scope = ProviderScope(str(uuid4()), ids, 999, 2026, clock.mono + 300, **scope_values)
    quota = QuotaLedger(
        tmp_path / "quota.sqlite3",
        scope_id=scope.scope_id,
        session_cap=20,
        allow_status_bootstrap=True,
    )
    http = MockHTTP(replies)
    client = ApiFootballClient(
        SecretValue("TEST_ONLY_HTTP_KEY"),
        quota,
        scope,
        opener=http,
        now_mono=lambda: clock.mono,
        now_utc=lambda: clock.utc,
        sleep=clock.advance,
    )
    return client, quota, http


@pytest.mark.parametrize(
    "change,diagnostic",
    [
        ("json", "INVALID_JSON"),
        ("envelope", "ENVELOPE_SHAPE"),
        ("errors", "ERRORS_SHAPE"),
        ("missing_paging", "PAGING_MISSING"),
        ("paging", "PAGING_INVALID"),
        ("response", "STATUS_RESPONSE_SHAPE"),
        ("results", "STATUS_RESULT_COUNT"),
        ("encoding", "CONTENT_ENCODING"),
        ("length", "CONTENT_LENGTH_MISMATCH"),
        ("fields", "STATUS_FIELDS"),
        ("auth", "NONE"),
    ],
)
@pytest.mark.parametrize("lookup", [True, False])
def test_probe_reports_finite_schema_diagnostics(
    tmp_path: Any, fake_clock: Any, change: str, diagnostic: str, lookup: bool
) -> None:
    from moj_discovery.live_config import load_live_config
    from tools.probe_football_provider import inspect_fixture_lookup, inspect_provider
    from tools.run_with_api_football_key import _report

    raw: Any = copy.deepcopy(STATUS)
    headers = {}
    if change == "json":
        raw = b"PRIVATE_INVALID_JSON"
    elif change == "envelope":
        raw = []
    elif change == "errors":
        raw["errors"] = "PRIVATE_ERROR"
    elif change == "missing_paging":
        del raw["paging"]
    elif change == "paging":
        raw["paging"]["total"] = 2
    elif change == "response":
        raw["response"] = []
    elif change == "results":
        raw["results"] = -1
    elif change == "encoding":
        headers["Content-Encoding"] = "PRIVATE_ENCODING"
    elif change == "length":
        headers["Content-Length"] = "1"
    elif change == "fields":
        raw["response"]["subscription"] = []
    elif change == "auth":
        raw["errors"] = {"token": "PRIVATE_AUTH_ERROR"}
    client, quota, http = make_client(
        tmp_path,
        fake_clock,
        [Reply(raw, headers=headers)],
        **({"fixture_ids": (), "lookup_date": "2026-09-09"} if lookup else {}),
    )
    with quota, client:
        result = (
            inspect_fixture_lookup(client)
            if lookup
            else inspect_provider(
                load_live_config(Path("config/live-batched.example.json")), client
            )
        )
        assert result["PROVIDER_DIAGNOSTIC"] == diagnostic
        assert result["PROBE_RESULT"] == "FAIL"
        assert result["KEY_CHECK"] == ("FAILED" if change == "auth" else "NOT_CHECKED")
        assert len(http.calls) == quota.count_attempts() == result["REQUEST_ATTEMPTS"] == 1
        assert "PRIVATE_" not in json.dumps(result)
        _report(result)


