        )
    ]
    client, _ = handshake()
    with pytest.raises(ValueError, match="SCHEMA"):
        client.send("CAPTURE_BATCH", body, KEY)


def test_wrong_hash_and_cross_stream_reject(synthetic_book: Any) -> None:
    for mutation in ["hash", "stream", "sequence", "generation"]:
        body = capture_body(synthetic_book)
        if mutation == "hash":
            body["events"][0]["content_hash"] = "f" * 64
        if mutation == "stream":
            body["stream_id"] = str(uuid4())
        if mutation == "sequence":
            body["last_sequence"] = "2"
        if mutation == "generation":
            body["generation"] = "9223372036854775808"
        client, _ = handshake()
        with pytest.raises(ValueError):
            client.send("CAPTURE_BATCH", body, KEY)


def test_pairing_expiry_one_use_and_handshake_deadline(fake_clock: Any) -> None:
    authority = PairingAuthority(RUN_ID, 300, clock=lambda: fake_clock.mono)
    ticket = authority.issue("CAPTURE_PRODUCER")
    assert len(ticket.key) == 32 and base64.urlsafe_b64encode(ticket.key).decode() not in repr(
        ticket
    )
    client = LiveSession(
        ticket.session_id, RUN_ID, "CLIENT", ticket.role, 300, clock=lambda: fake_clock.mono
    )
    hello = client.send(
        "HELLO",
        dict(run_id=RUN_ID, role=ticket.role, client_nonce=secrets.token_urlsafe(32)),
        ticket.key,
    )
    server, key = authority.consume(hello)
    with pytest.raises(ValueError):
        authority.consume(hello)
    fake_clock.advance(6)
    with pytest.raises(ValueError, match="TIMEOUT"):
        server.send(
            "WELCOME",
            dict(
                run_id=RUN_ID,
                client_nonce=server.client_nonce,
                server_nonce=secrets.token_urlsafe(32),
            ),
            key,
        )
    expired = authority.issue("UI_SUBSCRIBER")
    other = LiveSession(
        expired.session_id, RUN_ID, "CLIENT", expired.role, 300, clock=lambda: fake_clock.mono
    )
    data = other.send(
        "HELLO",
        dict(run_id=RUN_ID, role=expired.role, client_nonce=secrets.token_urlsafe(32)),
        expired.key,
    )
    fake_clock.advance(121)
    with pytest.raises(ValueError):
        authority.consume(data)


def test_offline_protocol_domain_and_duplicate_json_reject() -> None:
    client, server = handshake()
    ping = client.send(
        "PING", dict(run_id=RUN_ID, nonce=secrets.token_urlsafe(32), monotonic_us="0"), KEY
    )
    value = json.loads(ping)
    value["protocol"] = "BH_OFFLINE_WIRE_V1"
    with pytest.raises(ValueError):
        server.receive(json.dumps(value).encode(), KEY)
    with pytest.raises(ValueError):
        server.receive(ping[:-1] + b',"counter":"3"}', KEY)


def test_stop_revokes_unused_pairing() -> None:
    authority = PairingAuthority(RUN_ID, 120, clock=lambda: 0)
    ticket = authority.issue("UI_SUBSCRIBER")
    client = LiveSession(ticket.session_id, RUN_ID, "CLIENT", ticket.role, 120, clock=lambda: 0)
    data = client.send(
        "HELLO",
        dict(run_id=RUN_ID, role=ticket.role, client_nonce=secrets.token_urlsafe(32)),
        ticket.key,
    )
    authority.revoke()
    with pytest.raises(ValueError):
        authority.consume(data)
    with pytest.raises(ValueError):
        authority.issue("UI_SUBSCRIBER")


def context(book: Any) -> Any:
    return {
        "run_id": RUN_ID,
        "allowed_extension_origin": ORIGIN,
        "deadline_mono": time.monotonic() + 120,
        "source_kind": "MOCK",
        "capture_streams": {
            OPERATOR: {
                "binding_id": book["binding_id"],
                "binding_revision": book["binding_revision"],
                "operator_fixture_id": book["operator_fixture_id"],
                "generation": "0",
                "profile_hash": book["profile_hash"],
                "document_epoch": book["document_epoch"],
                "markets": {
                    "FT": {
                        "market_id": book["market_id"],
                        "selections": {s: v["selection_id"] for s, v in book["selections"].items()},
                    }
                },
            }
        },
    }


async def paired_socket(authority: Any, role: Any = "CAPTURE_PRODUCER") -> Any:
    ticket = authority.issue(role)
    socket = await connect(
        "ws://127.0.0.1:8765/live", origin=Origin(ORIGIN), compression=None, proxy=None
    )
    session = LiveSession(ticket.session_id, authority.run_id, "CLIENT", role, authority.deadline)
    await socket.send(
        session.send(
            "HELLO",
            dict(run_id=authority.run_id, role=role, client_nonce=secrets.token_urlsafe(32)),
            ticket.key,
        ).decode()
    )
    welcome_raw = await socket.recv()
    assert isinstance(welcome_raw, str)
    welcome = session.receive(welcome_raw.encode(), ticket.key)
    await socket.send(session.send("READY", welcome["body"], ticket.key).decode())
    ready_raw = await socket.recv()
    assert isinstance(ready_raw, str)
    session.receive(ready_raw.encode(), ticket.key)
    return socket, session, ticket.key


def test_socket_commit_before_ack_and_role_rejection(tmp_path: Any, synthetic_book: Any) -> None:
    async def scenario() -> Any:
        with LiveStore(tmp_path / "run" / "live.sqlite3", **metadata()) as store:
            register(store)
            ctx = context(synthetic_book)
            authority = PairingAuthority(RUN_ID, ctx["deadline_mono"])
            receiver = await serve_live_receiver(ctx, store, authority)
            try:
                socket, client, key = await paired_socket(authority)
                async with socket:
                    body = capture_body(synthetic_book)
                    await socket.send(client.send("CAPTURE_BATCH", body, key).decode())
                    ack = client.receive((await socket.recv()).encode(), key)
                    assert ack["message_type"] == "ACK"
                    assert (
                        store.read_projection(synthetic_book["binding_id"])["books"]["FT"]
                        == synthetic_book
                    )
                subscriber, ui, ui_key = await paired_socket(authority, "UI_SUBSCRIBER")
                async with subscriber:
                    # Bypass client helper deliberately; server still enforces authenticated role.
                    forbidden = encode_frame(
                        dict(
                            protocol="BH_LIVE_WIRE_V1",
                            session_id=ui.session_id,
                            direction="CLIENT_TO_BACKEND",
                            counter="3",
                            message_type="CAPTURE_BATCH",
                            body=body,
                        ),
                        ui_key,
                    )
                    await subscriber.send(forbidden.decode())
                    with pytest.raises(ConnectionClosed):
                        await subscriber.recv()
                assert store.cursor(OPERATOR) == (1, body["events"][0]["content_hash"])
            finally:
                await receiver.close()

    asyncio.run(scenario())


def test_wrong_origin_path_and_key_write_nothing(tmp_path: Any, synthetic_book: Any) -> None:
    async def scenario() -> Any:
        with LiveStore(tmp_path / "run" / "live.sqlite3", **metadata()) as store:
            register(store)
            ctx = context(synthetic_book)
            authority = PairingAuthority(RUN_ID, ctx["deadline_mono"])
            receiver = await serve_live_receiver(ctx, store, authority)
            try:
                for origin, path in [
                    ("https://example.invalid", "/live"),
                    (ORIGIN, "/offline"),
                    (ORIGIN, "/live?secret=x"),
                ]:
                    with pytest.raises(InvalidStatus):
                        async with connect(
                            "ws://127.0.0.1:8765" + path, origin=Origin(origin), proxy=None
                        ):
                            pass
                ticket = authority.issue("CAPTURE_PRODUCER")
                client = LiveSession(
                    ticket.session_id, RUN_ID, "CLIENT", ticket.role, authority.deadline
                )
                async with connect(
                    "ws://127.0.0.1:8765/live", origin=Origin(ORIGIN), proxy=None
                ) as socket:
                    await socket.send(
                        client.send(
                            "HELLO",
                            dict(
                                run_id=RUN_ID,
                                role=ticket.role,
                                client_nonce=secrets.token_urlsafe(32),
                            ),
                            KEY,
                        ).decode()
                    )
                    with pytest.raises(ConnectionClosed):
                        await socket.recv()
                assert store.cursor(OPERATOR)[0] == 0
            finally:
                await receiver.close()

    asyncio.run(scenario())"""Actual selected browser/WSL path; synthetic fixture oracle stays in Python."""

# ruff: noqa: E501 -- Fixed isolated test programs.
import asyncio
import base64
import hashlib
import json
import os
from dataclasses import replace
from pathlib import Path
from typing import Any

from tests.live.test_live_service import make_service
from tests.live.test_live_spool_bridge import safe_browser_environment
from tools import offline_browser
from tools.qualify_live_platform import CHROME, ROOT, WindowsBrowser, build_live_extension, hashes

PAGE = r"""
const panes={};
const wait=()=>new Promise(r=>setTimeout(r,300));
function open(){for(const name of ['panel','workspace']){const f=document.createElement('iframe');
 f.src='../live/'+name+'.html';document.body.append(f);panes[name]=f;}}
open();
const observe=()=>Object.fromEntries(Object.entries(panes).map(([k,f])=>[k,{
 text:f.contentDocument.body.textContent,revision:f.contentDocument.querySelector('section')?.dataset.revision,
 input:f.contentDocument.querySelector('input')?.value}]));
globalThis.offlineProbe={command:async m=>{
 if(m.operation==='CLOSE_PANELS'){for(const [k,f] of Object.entries(panes)){f.remove();delete panes[k];}return {status:'OK',observed:observe()};}
 if(m.operation==='OPEN_PANELS')open();
 if(m.operation==='WRONG_PATH'){return {status:'OK',observed:await new Promise(ok=>{let opened=false;const w=new WebSocket('ws://127.0.0.1:8765/wrong');w.onopen=()=>{opened=true;w.close()};w.onclose=()=>ok({opened});})};}
 for(let i=0;i<60 && !panes.panel?.contentDocument?.querySelector('input');i++)await wait();
 if(m.operation==='PAIR'){const d=panes.panel.contentDocument;d.querySelector('input').value=m.ticket;d.querySelector('form').requestSubmit();}
 else if(!['OBSERVE','OPEN_PANELS'].includes(m.operation))throw Error('E_TEST_OPERATION');
 await wait();return {status:'OK',observed:observe()};
}};
"""


def private_driver(output: Path) -> Path:
    driver = (ROOT / "tools/chrome_pipe.cjs").read_text()
    driver = "const pb15Versions=new Map(),pb15History=[];\n" + driver
    needle = "const value = JSON.parse(raw), waiter = pending.get(value.id);"
    assert needle in driver
    driver = driver.replace(
        needle,
        needle
        + "\nif(value.method==='ServiceWorker.workerVersionUpdated')for(const v of value.params.versions){pb15Versions.set(v.versionId,v);pb15History.push(v);}",
    )
    needle = "let document;"
    driver = driver.replace(
        needle, "await call('ServiceWorker.enable',{},attached.sessionId);\n" + needle
    )
    needle = "const task = evaluate(attached.sessionId, expression, true).then(result => {"
    assert needle in driver
    driver = driver.replace(
        needle,
        """const task = (async()=>{
      if(request.operation==='PB15_STOP_WORKER'){
        const workers=[...pb15Versions.values()].filter(v=>v.scriptURL===config.origin+'/src/live/background.js'&&v.runningStatus==='running');
        if(workers.length!==1)throw Error('E_TEST_WORKER_IDENTITY');
        for(const v of workers)await call('ServiceWorker.stopWorker',{versionId:v.versionId},attached.sessionId,true);
        await new Promise(r=>setTimeout(r,500));
        return {status:'OK',observed:{before:workers,after:pb15History}};
      }
      return await evaluate(attached.sessionId,expression,true);
    })().then(result => {""",
    )
    (output / "tools").mkdir(parents=True)
    path = output / "tools/chrome_pipe.cjs"
    path.write_text(driver)
    return path


def test_actual_selected_platform_bridge_and_worker_repair(
    tmp_path: Path,
    disabled_live_config: Any,
    fake_clock: Any,
    synthetic_provider_response: Any,
    synthetic_book: Any,
    monkeypatch: Any,
) -> None:
    selected = os.environ.get("PB_PLATFORM", "WINDOWS_CHROME_WSL2")
    assert selected in {"WINDOWS_CHROME_WSL2", "LINUX_CHROME"}
    extension, origin = build_live_extension(tmp_path / "build")
    production_hashes = hashes(extension)
    assert "export " not in (extension / "src/live/dom_reader.js").read_text()
    assert not any("offline" in name or "test" in name for name in production_hashes)
    assert "validateRaw" not in (extension / "live-validators.js").read_text()
    # Private page is added only after binding the production graph.
    (extension / "src/offline").mkdir()
    (extension / "src/offline/page.html").write_text(
        '<!doctype html><title>PB-15 isolated synthetic</title><script type="module" src="page.js"></script>'
    )
    (extension / "src/offline/page.js").write_text(PAGE)
    driver = private_driver(tmp_path / "driver")
    service, http, book, _ = make_service(
        tmp_path / "service",
        disabled_live_config,
        fake_clock,
        synthetic_provider_response,
        synthetic_book,
        monkeypatch,
    )
    service.admitted = replace(service.admitted, extension_origin=origin)
    service._receiver_context["allowed_extension_origin"] = origin
    observations = []
    browser: Any = None

    def ticket() -> str:
        result: dict[str, Any] = {
            "version": 1,
            "runId": service.admitted.run_id,
            "durationSeconds": 120,
        }
        for name, role in (("ui", "UI_SUBSCRIBER"), ("capture", "CAPTURE_PRODUCER")):
            pair = service.pairing.issue(role)
            result[name] = {
                "sessionId": pair.session_id,
                "key": base64.urlsafe_b64encode(pair.key).decode().rstrip("="),
            }
        return json.dumps(result)

    async def scenario() -> None:
        nonlocal browser
        try:
            await service.start()
            await service.tick()
            server = service.receiver.server
            assert server is not None
            addresses = sorted({s.getsockname()[0] for s in server.sockets})
            assert addresses == ["127.0.0.1"]
            safe_browser_environment(monkeypatch)
            if selected == "WINDOWS_CHROME_WSL2":
                browser = await asyncio.to_thread(WindowsBrowser, extension, origin, driver)
            else:
                with monkeypatch.context() as scoped:
                    scoped.setattr(offline_browser, "ROOT", driver.parent.parent)
                    browser = await asyncio.to_thread(
                        offline_browser.OfflineBrowser, tmp_path / "browser", extension, origin
                    )

            async def command(operation: str, **values: Any) -> Any:
                result = await asyncio.to_thread(
                    browser.command, {"operation": operation, **values}
                )
                observations.append({"operation": operation, "result": result})
                assert result["status"] == "OK"
                return result["observed"]

            async def paired() -> Any:
                seen = await command("PAIR", ticket=ticket())
                for _ in range(20):
                    if all("CONNECTED" in v["text"] and v.get("revision") for v in seen.values()):
                        return seen
                    seen = await command("OBSERVE")
                raise AssertionError("Actual Chrome did not receive authenticated WSL projection")

            first = await paired()
            assert first["panel"]["revision"] == first["workspace"]["revision"]
            assert all(v["input"] == "" for v in first.values())
            assert service.receiver.connected("CAPTURE_PRODUCER")
            assert await command("WRONG_PATH") == {"opened": False}
            count = len(http.paths)
            assert await command("CLOSE_PANELS") == {}
            assert service.receiver.connected("UI_SUBSCRIBER")
            await command("OPEN_PANELS")
            assert len(http.paths) == count
            stopped = await command("PB15_STOP_WORKER")
            version = stopped["before"][0]["versionId"]
            assert any(
                v["versionId"] == version and v["runningStatus"] == "stopped"
                for v in stopped["after"]
            )
            for _ in range(20):
                if not service.receiver.connected("CAPTURE_PRODUCER"):
                    break
                await asyncio.sleep(0.1)
            assert not service.receiver.connected("CAPTURE_PRODUCER")
            assert service.view(book["binding_id"])["market_eligible"] is False
            repaired = await paired()
            assert repaired["panel"]["revision"] == repaired["workspace"]["revision"]
            assert len(http.paths) == count
            local = await command("OBSERVE")
            assert all(
                "SYNTHETIC" in v["text"] and "MODEL_NOT_QUALIFIED" in v["text"]
                for v in local.values()
            )
            (tmp_path / "observed-bridge.json").write_text(
                json.dumps(
                    {
                        "platform": selected,
