) -> None:
    folder = tmp_path / ".local/part-b"
    folder.mkdir(parents=True)
    refs, reports, called = {}, {}, []
    for scope in needed:
        run = folder / ("run-" + str(scope))
        run.mkdir()
        report = dict(
            schema_version="part-b-live-qualification/v1",
            run_id=str(scope),
            run_directory=str(run),
            source_tree_sha256="a" * 64,
            config_sha256="b" * 64,
            scope={"max_matches": scope},
            observed_fixture_ids=list(range(scope)),
            ft_checks_by_binding={str(i): 3 for i in range(scope)},
            artifacts={},
            real_http_attempts=10,
            LIVE_READ_ONLY_PASS=True,
        )
        reports[scope] = report
        path = folder / (str(scope) + ".json")
        path.write_text(json.dumps(report))
        refs[str(scope)] = dict(
            path=str(path.relative_to(tmp_path)),
            sha256=hashlib.sha256(path.read_bytes()).hexdigest(),
        )

    def requalify(run: Any, *, expected_scope: int) -> Any:
        assert run == folder / ("run-" + str(expected_scope))
        called.append(expected_scope)
        return reports[expected_scope]

    monkeypatch.setattr(gate, "qualify_recorded_run", requalify)
    config = LiveConfig({"runtime": {"max_matches": limit}}, "b" * 64)
    review = {"scope": {"previous_scope_refs": refs}}
    gate.verify_preceding_scope(config, review, tmp_path)
    assert called == needed
    if needed:
        with pytest.raises(ValueError, match="REQUIRED"):
            gate.verify_preceding_scope(config, {"scope": {}}, tmp_path)
        reports[needed[0]]["LIVE_READ_ONLY_PASS"] = False
        with pytest.raises(ValueError, match="NOT_QUALIFIED"):
            gate.verify_preceding_scope(config, review, tmp_path)
        path = folder / (str(needed[0]) + ".json")
        path.write_text("{}")
        with pytest.raises(ValueError, match="HASH"):
            gate.verify_preceding_scope(config, review, tmp_path)"""Profile evidence checks. An empty index proves no real operator capability."""

import hashlib
import json
from datetime import UTC, datetime
from pathlib import Path
from typing import Any

import pytest

from moj_discovery.live_config import private_path
from moj_discovery.operator_profile import ProfileEvidence, validate_extraction_profile


def verify_admitted_profile_index(index: dict[str, Any], root: Path) -> list[str]:
    if (
        set(index) != {"schema_version", "status", "profiles"}
        or index["schema_version"] != "part-b-admitted-profile-index/v1"
        or type(index["profiles"]) is not list
    ):
        raise ValueError("E_PROFILE_INDEX")
    if index["status"] == "WAITING_OPERATOR_SAMPLE" and not index["profiles"]:
        return []
    if index["status"] != "OBSERVED_REAL" or not 1 <= len(index["profiles"]) <= 5:
        raise ValueError("E_PROFILE_INDEX_NOT_OBSERVED")

    def artifact(ref: str, expected: str) -> Path:
        path = private_path(ref, root=root, must_exist=True)
        if path.stat().st_size > 65536 or hashlib.sha256(path.read_bytes()).hexdigest() != expected:
            raise ValueError("E_PROFILE_INDEX_HASH")
        return path

    admitted = []
    for row in index["profiles"]:
        if type(row) is not dict or set(row) != {
            "profile",
            "profile_sha256",
            "review",
            "review_sha256",
            "samples",
            "bindings",
        }:
            raise ValueError("E_PROFILE_INDEX_FIELDS")
        value = json.loads(artifact(row["profile"], row["profile_sha256"]).read_text())
        if value["source_kind"] != "OBSERVED_REAL" or value["status"] != "ACCEPTED":
            raise ValueError("E_PROFILE_INDEX_SYNTHETIC_OR_DRAFT")
        profile = validate_extraction_profile(
            value,
            ProfileEvidence(
                root,
                datetime.now(UTC),
                tuple(artifact(ref, sha) for ref, sha in row["samples"].items()),
                artifact(row["review"], row["review_sha256"]),
                tuple(row["bindings"]),
            ),
        )
        if (
            not profile._real_admitted
            or "FT" not in profile.public["horizons"]
            or any(b["orientation_status"] != "VERIFIED" for b in row["bindings"])
        ):
            raise ValueError("E_PROFILE_INDEX_SCOPE")
        admitted.append(profile.profile_hash)
    if len(set(admitted)) != len(admitted):
        raise ValueError("E_PROFILE_INDEX_DUPLICATE")
    return admitted


def test_missing_or_synthetic_index_is_never_real_acceptance(tmp_path: Path) -> None:
    pending = {
        "schema_version": "part-b-admitted-profile-index/v1",
        "status": "WAITING_OPERATOR_SAMPLE",
        "profiles": [],
    }
    assert verify_admitted_profile_index(pending, tmp_path) == []
    for value in (
        {**pending, "status": "OBSERVED_REAL"},
        {**pending, "profiles": [{"profile": ".env"}]},
        {**pending, "live_pass": True},
    ):
        with pytest.raises(ValueError):
            verify_admitted_profile_index(value, tmp_path)


def test_index_stays_pending_or_reopens_actual_reviewed_samples() -> None:
    root = Path(__file__).resolve().parents[2]
    index = json.loads((Path(__file__).parent / "fixtures/admitted-profile-index.json").read_text())
    actual = verify_admitted_profile_index(index, root)
    assert bool(actual) == (index["status"] == "OBSERVED_REAL")import hashlib
import json
from datetime import UTC, datetime
from pathlib import Path
from typing import Any
from uuid import uuid4

import pytest

from moj_discovery.operator_profile import (
    ProfileEvidence,
    activate_profile,
    parse_decimal_price,
    validate_extraction_profile,
)
from tests.live.test_live_store import binding

ROOT = Path(__file__).resolve().parents[2]
NOW = datetime(2026, 9, 9, 18, tzinfo=UTC)


def profile() -> Any:
    schema = json.loads(
        (ROOT / "contracts/live_readonly/v1/operator-profile.schema.json").read_text()
    )
    fields = schema["properties"]["selectors"]["required"]
    return dict(
        schema_version="operator-extraction-profile/v1",
        profile_id=str(uuid4()),
        profile_version="1",
        status="DRAFT",
        source_kind="SYNTHETIC_TEST",
        origin="https://example.invalid",
        exact_paths=["/match/101"],
        permitted_fixture_ids=["SYNTHETIC-101"],
        locale="en",
        price_parser="DECIMAL_DOT",
        selectors={
            k: "#"
            + ("TEST_ONLY_MATCH" if k == "match_root" else k.replace("_", "-"))
            + (" > .selection-id" if k.endswith("_selection") else "")
            for k in fields
        },
        horizons=["FT"],
        observation_mode="FIXED_DOM_READONLY",
        evidence_hashes=[],
        capture_source_hash="a" * 64,
        reviewed_source_hash=None,
        expires_at=None,
        max_matches=1,
    )


def sample(value: Any) -> Any:
    return dict(
        schema_version="operator-profile-sample/v1",
        source_kind="SYNTHETIC_TEST",
        profile_id=value["profile_id"],
        origin=value["origin"],
        path="/match/101",
        fixture_id="SYNTHETIC-101",
        home_id="SYNTHETIC-H",
        away_id="SYNTHETIC-A",
        markets=[
            dict(
                market_id="SYNTHETIC-FT",
                horizon="FT",
                settlement_basis="NORMAL_TIME_INCLUDING_STOPPAGE",
                selections={side: "SYNTHETIC-" + side for side in ["HOME", "DRAW", "AWAY"]},
                labels={
                    "horizon": "FT",
                    "status": {"OPEN": "OPEN"},
                    "period": {"H1": "1H"},
                    "score_separator": "EN_DASH",
                },
            )
        ],
        field_map={
            k: {
                "selector": s,
                "reader": "ROOT_NODE"
                if k == "match_root"
                else "DATA_MARKET_ID"
                if k == "market_root"
                else "TEXT_CONTENT",
            }
            for k, s in value["selectors"].items()
            if s is not None
        },
    )


def evidence_for(tmp_path: Any, value: Any, observed: Any) -> Any:
    directory = tmp_path / ".local/part-b/operator"
    directory.mkdir(parents=True, exist_ok=True)
    path = directory / "sample.json"
    path.write_text(json.dumps(observed))
    value["evidence_hashes"] = [hashlib.sha256(path.read_bytes()).hexdigest()]
    return ProfileEvidence(tmp_path, NOW, (path,), fixture_bindings=(binding(),))


def test_draft_is_inert_and_synthetic_target_explicit() -> None:
    value = profile()
    draft = validate_extraction_profile(value, ProfileEvidence(ROOT, NOW))
    assert draft.status == "DRAFT"
    assert draft.field_map["home_odds"] == {"selector": "#home-odds", "reader": "TEXT_CONTENT"}
    assert activate_profile(draft, target="SYNTHETIC_TEST")["source_kind"] == "SYNTHETIC_TEST"
    with pytest.raises(ValueError, match="INACTIVE"):
        activate_profile(draft, target="OPERATOR")
    public = draft.public
    public["selectors"]["home_odds"] = "input"
    assert draft.public == value


