    monkeypatch.setattr(launcher, "obtain_api_football_key", lambda *a: pytest.fail("key read"))
    assert (
        launcher.main(
            [
                "--action",
                "probe",
                "--config",
                "config/live-batched.example.json",
                "--intent",
                ".local/part-b/absent-intent.json",
            ]
