def _git(root: Path, *args: str) -> str:
    git = shutil.which("git")
    assert git is not None
    return subprocess.check_output(  # noqa: S603 -- local disposable Git fixture.
        [git, "-C", str(root), *args], text=True, stderr=subprocess.PIPE,
    ).strip()


def _repository(directory: Path, object_format: str = "sha1") -> tuple[Path, str]:
    root = directory / "runtime"
    root.mkdir(parents=True)
    _git(root, "init", "-b", "main", "--object-format=" + object_format)
    _git(root, "config", "user.name", "Descendant Test")
    _git(root, "config", "user.email", "descendant@example.invalid")
    ancestor = _commit(root, "audited.txt", "audited")
    _commit(root, "repair.txt", "repair")
    return root, ancestor


def _config(directory: Path, root: Path, ancestor: str) -> Any:
    from tools.full_verifier_config import load_controller_config

    payload = json.loads(SOURCE_CONFIG.read_bytes())
    pack = directory / "authoring/pack"
    evidence = directory / "evidence"
    evidence.mkdir()
    payload.update(
        current_checkout_root=str(root), governed_source_pack=str(pack),
        evidence_root=str(evidence), audited_runtime_ancestor=ancestor,
        external_authoring_tests=str(directory / "authoring/authoring-tests"),
        external_authoring_command={
            "cwd": str(directory / "authoring"),
            "argv": ["uv", "run", "--frozen", "--offline", "python", "-I", "-B", "tests.py"],
        },
    )
    for key, value in payload["receipts"].items():
        payload["receipts"][key] = str(evidence / Path(value).name)
    for key, value in payload["qualification_evidence"].items():
        parent = evidence if key in {"p03_proof", "p04_proof"} else evidence / key
        payload["qualification_evidence"][key] = str(parent / Path(value).name)
    source = pack / "docs/configs/full-verifier-controller.v2.json"
    source.parent.mkdir(parents=True)
    source.write_text(json.dumps(payload, sort_keys=True))
    path = directory / "controller.json"
    path.write_bytes(source.read_bytes())
    return load_controller_config(path)


def _write(path: Path, value: object) -> bytes:
    raw = json.dumps(value, sort_keys=True, separators=(",", ":")).encode() + b"\n"
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(raw)
    return raw


def _refresh_current_phase_fixtures(config: Any) -> None:
    """Structural TEST_ONLY_NOT_EXECUTED inputs; never actual command evidence.

    Keep the phase producer and verifier real while binding disposable command
    records to the fixture's current Git state and source declarations.
    """
    from tools import phase_evidence as phase
    from tools import run_command_registry as commands

    assert config.current_checkout_root != ROOT
    assert config.evidence_root.is_relative_to(config.current_checkout_root.parent)
    spec = phase.contract(config)
    if spec is None:
        return
    identity = commands._git_source_identity(config.current_checkout_root)
    candidate = json.loads(config.candidate_command_evidence.read_bytes())
    inputs = {
        name: hashlib.sha256((config.governed_source_pack / 'docs' / name).read_bytes()).hexdigest()
        for name in (
            'tasks/task-manifest.v6.3.6.json', 'registries/artifact-ownership.v1.json',
            'schemas/artifact-ownership.schema.json', 'registries/task-command-registry.v1.json',
            'registries/review-command-registry.v1.json',
            'registries/cybersecurity-command-registry.v1.json',
            'registries/baseline-replay-command-registry.v1.json',
        )
    }
    registry = phase.expected_commands(config)
    extras = []
    logs = config.evidence_root / 'command-logs'
    logs.mkdir(exist_ok=True)
    for result in candidate['results']:
        for stream in ('stdout', 'stderr'):
            assert result[stream + '_sha256'] == hashlib.sha256(b'').hexdigest()
            (logs / (result['command_id'] + '.' + stream)).write_bytes(b'')
    for identifier in sorted(phase.CURRENT_COMMANDS):
        raw = _write(logs / (identifier + '.stdout'), {
            'fixture': 'TEST_ONLY_NOT_EXECUTED',
            'gate': 'CURRENT_DECLARATION_VALID' if identifier == 'VALIDATE_CURRENT_DECLARATION'
                else 'CURRENT_DESCENDANT_SOURCE_VALID',
            'result': 'PASS', 'production_authority': 'NONE', 'source_identity': identity,
            'contract_sha256': hashlib.sha256(
                (config.governed_source_pack / phase.CONTRACT).read_bytes()
            ).hexdigest(),
            'input_hashes': inputs, 'adopted_source': spec['adopted_source'],
            'historical_receipt_sha256': spec['historical_migration_sha256'],
            'historical_regressions': {'exit_code': 0}, 'historical_acceptance': 'NOT_INFERRED',
        })
        (logs / (identifier + '.stderr')).write_bytes(b'')
        extras.append({
            **{key: registry[identifier][key] for key in (
                'command_id', 'argv', 'cwd', 'expected_exit',
            )},
            'exit_code': 0, 'passed': True,
            'stdout_sha256': hashlib.sha256(raw).hexdigest(), 'stdout_size_bytes': str(len(raw)),
            'stderr_sha256': hashlib.sha256(b'').hexdigest(), 'stderr_size_bytes': '0',
        })
    _write(config.evidence_root / 'CURRENT_INPUTS.json', {
        'source_identity': identity, 'results': extras, 'controller_binding': config.binding(),
    })
    for task in spec['phases']:
        # Only this helper's earlier disposable records may be refreshed.
        path = config.evidence_root / (task + '.json')
        if path.exists():
            assert json.loads(path.read_bytes()).get('schema_version') == 'current-phase-proof/v1'
            path.unlink()
    phase.issue_phases(config, extras, identity)


def _sync_fixture_sources(
    source: Path, pack: Path, root: Path, monkeypatch: pytest.MonkeyPatch,
    witnesses: dict[str, bytes],
) -> None:
    """Approved path-only disposable source transport and official materialization."""
    from tools.sync_pack_assets import _tree_files, sync_pack_assets

    for original in _tree_files(source):
        target = pack / original.relative_to(source)
        if not target.exists():
            target.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(original, target)
    relative = "docs/registries/task-command-registry.v1.json"
    raw = (source / relative).read_bytes()
    witnesses[relative] = raw
    registry = json.loads(raw)
    original_config = json.loads(SOURCE_CONFIG.read_bytes())
    replacements = {
        original_config["current_checkout_root"]: str(root),
        original_config["governed_source_pack"]: str(pack),
        "/home/thenam176/betting-helper/hybrid-discovery-v6.3.6-authoring/runtime": str(root),
        "/home/thenam176/betting-helper/hybrid-discovery-v6.3.6-authoring/pack": str(pack),
    }

    def token(value: str) -> str:
        for old, new in replacements.items():
            if value == old or value.startswith(old + "/"):
                return new + value[len(old):]
        return value

    for command in registry["commands"]:
        command["cwd"] = token(command["cwd"])
        command["argv"] = [token(item) for item in command["argv"]]
    restored = deepcopy(registry)
    for original, transported in zip(
        json.loads(raw)["commands"], restored["commands"], strict=True,
    ):
        assert transported["cwd"] == token(original["cwd"])
        assert transported["argv"] == [token(item) for item in original["argv"]]
        transported["cwd"], transported["argv"] = original["cwd"], original["argv"]
    assert restored == json.loads(raw)
    _write(pack / relative, registry)
    sync_pack_assets(pack, root)
    spec = importlib.util.spec_from_file_location(
        "descendant_fixture_materializer",
        source.parent / "authoring-tools/build_task_command_registry.py",
    )
    assert spec is not None and spec.loader is not None
    module = importlib.util.module_from_spec(spec)
    with monkeypatch.context() as importing:
        importing.setattr(sys, "dont_write_bytecode", True)
        spec.loader.exec_module(module)
    module.build_task_command_registry(
        json.loads((pack / "docs/tasks/task-manifest.v6.3.6.json").read_bytes()),
        pack / relative, pack / "docs/configs", root / "task-command-registry.json",
        review_config_profile="current",
    )
    assert (root / "task-command-registry.json").read_bytes() == (pack / relative).read_bytes()
    assert (root / "vendor/hybrid-discovery-v6.3.6" / relative).read_bytes() == (
        pack / relative
    ).read_bytes()
    _git(root, "add", "--force", "vendor", "schema-lock.json",
         "task-command-registry.json", "review-config")
    _git(root, "commit", "-m", "official isolated source fixture sync")


