def test_candidate_proof_and_release_mapping_mutations_execute_real_operations(
    tmp_path: Path,
) -> None:
    result = runner.run_clock_vector_qualification(PACK, ROOT, evidence_dir=tmp_path)
    rows = {row["case_id"]: row for row in result["mutation_records"]}
    for name in ("candidate_proof_corruption", "release_mapping_close"):
        assert rows[name]["executed"] is True
        assert rows[name]["detected"] is True
        assert runner.verify_record(rows[name])
    candidate = rows["candidate_proof_corruption"]["actual"]
    assert candidate["control"]["actual"]["python"]["accepted"] is True
    assert candidate["trial"]["actual"]["python"]["error"] == "E_RESNAPSHOT_CANDIDATE_BINDING"
    release = rows["release_mapping_close"]["actual"]
    for phase in ("control", "trial"):
        for language in ("python", "typescript"):
            assert "mapping_close_executed" not in release[phase]["actual"][language]
            assert release[phase]["operation_metadata"][language][
                "mapping_close_executed"
            ] is True
    assert release["control"]["actual"]["python"]["accepted"] is True
    assert release["trial"]["actual"]["python"]["error"] == "E_MAPPING_CLOSED"


def test_release_mapping_guard_bypass_makes_mutation_survive_and_fail_qualification(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch,
) -> None:
    original = runner._mutations

    def bypass(*args: Any, **kwargs: Any) -> list[dict[str, Any]]:
        return original(*args, **kwargs, bypass_release_mapping_guard=True)

    monkeypatch.setattr(runner, "_mutations", bypass)
    result = runner.run_clock_vector_qualification(PACK, ROOT, evidence_dir=tmp_path)
    mutation = next(
        row for row in result["mutation_records"] if row["case_id"] == "release_mapping_close"
    )
    assert mutation["executed"] is True
    assert mutation["detected"] is False
    assert mutation["actual"]["trial"]["status"] == "PASS"
    assert result["mutation_survivors"] == 1
    assert result["result"] == "FAIL"


@pytest.mark.parametrize("damage", ["tamper", "remove"])
def test_imported_coherence_javascript_is_bound_and_damage_fails_evidence(
    tmp_path: Path, damage: str,
) -> None:
    result = runner.run_clock_vector_qualification(PACK, ROOT, evidence_dir=tmp_path)
    row = next(item for item in result["records"] if item["case_id"] == "RELEASE-POS-01")
    key = "contracts/clock-coherence.js"
    descriptor = row["typescript_executable_artifacts"][key]
    executable = Path(descriptor["path"])
    assert executable.resolve().is_relative_to(tmp_path.resolve())
    assert descriptor["sha256"] == hashlib.sha256(executable.read_bytes()).hexdigest()
    original = executable.read_bytes()
    try:
        if damage == "tamper":
            executable.write_bytes(original + b"\n// tampered\n")
        else:
            executable.unlink()
        checked = evidence_gate.aggregate_repair_evidence([row["case_id"]], [row])
        assert checked["result"] == "FAIL"
        assert checked["errors"] == [
            {"case_id": row["case_id"], "error": "E_REPAIR_ARTIFACT"}
        ]
    finally:
        executable.write_bytes(original)


def test_coherently_rehashed_clock_graph_fails_shared_replay_but_valid_copy_passes(
    tmp_path: Path,
) -> None:
    original = tmp_path / "original"
    result = runner.run_clock_vector_qualification(PACK, ROOT, evidence_dir=original)
    row = copy.deepcopy(result["records"][0])
    closure = tmp_path / "closure"
    closure.mkdir()
    manifest = write_closed_inventory(
        collect_retained_sources(row, retained_boundaries=(original,), live_roots=(ROOT,)),
        closure / "inventory.json",
    )
    artifacts = RetainedArtifactIO.from_manifest(manifest, closure / "retained")
    # Replay only the immutable closure even when generated and captured files disappear.
    hidden = tmp_path / "hidden-original"
    original.rename(hidden)
    generated = ROOT / "extension/.test-build/src/contracts/clock-coherence.js"
    compiled = generated.read_bytes()
    try:
        generated.unlink()
        assert evidence_gate.aggregate_repair_evidence(
            [row["case_id"]], [row], artifacts=artifacts
        )["result"] == "PASS"
    finally:
        generated.write_bytes(compiled)
        hidden.rename(original)

    key = "contracts/clock-coherence.js"
    descriptor = row["typescript_executable_artifacts"][key]
    executable = Path(descriptor["path"])
    executable.write_bytes(executable.read_bytes() + b"\n// coherently rehashed\n")
    descriptor["sha256"] = hashlib.sha256(executable.read_bytes()).hexdigest()
    for phase in ("before", "after"):
        row["typescript_execution_binding"][phase][key] = descriptor["sha256"]
    binding = row["typescript_execution_binding_artifact"]
    content = runner._bytes(row["typescript_execution_binding"])
    Path(binding["path"]).write_bytes(content)
    binding["sha256"] = hashlib.sha256(content).hexdigest()
    changed = tmp_path / "changed-closure"
    changed.mkdir()
    changed_manifest = write_closed_inventory(
        collect_retained_sources(row, retained_boundaries=(original,), live_roots=(ROOT,)),
        changed / "inventory.json",
    )
    rehashed = RetainedArtifactIO.from_manifest(changed_manifest, changed / "retained")
    for transport in (None, rehashed):
        checked = evidence_gate.aggregate_repair_evidence(
            [row["case_id"]], [row], artifacts=transport
        )
        assert checked["result"] == "FAIL"
        assert checked["errors"] == [
            {"case_id": row["case_id"], "error": "E_REPAIR_ARTIFACT"}
        ]


def test_same_wrong_evaluators_fail_independent_numeric_oracle(
