def test_missing_duplicate_and_tampered_artifacts_fail(tmp_path: Path) -> None:
    result = runner.run_clock_vector_qualification(PACK, ROOT, evidence_dir=tmp_path)
    rows = result["records"]
    for changed in (rows[1:], [*rows, copy.deepcopy(rows[0])]):
