        {"command_id": command_id, "cwd": str(ROOT), "argv": [command_id], "expected_exit": 0}
        for command_id in (
            "VERIFY_V636_P07_T01",
            "VERIFY_V636_P07_T02",
            "VERIFY_V636_P07_T03",
        )
    ]
