import copy
import hashlib
import importlib
import json
import os
import shutil
import signal
from pathlib import Path
from typing import Any

import pytest

from moj_discovery.store import RunStore
from tests.repairs.test_shared_ingest_persistence import corrupt_journal, observation
from tools.restart_state_reader import read_restart_state

ROOT = Path(__file__).resolve().parents[2]
PACK = ROOT / "vendor/hybrid-discovery-v6.3.6"


def runner() -> Any:
    module = importlib.import_module("tools.run_loopback_ack_crash_matrix")
    assert hasattr(module, "run_backend_case"), "BH-R03: actual backend crash path absent"
    return module


def entry(prefix: str) -> dict[str, Any]:
    entries = json.loads((PACK / "docs/registries/crash-harness-registry.v1.json").read_text())
    return next(row for row in entries["entries"] if row["vector_id"].startswith(prefix))


@pytest.mark.parametrize(
    "prefix", ["SEND-01", "SQL-01", "SQL-02", "SQL-03", "SQL-04", "SQL-05", "SQL-07", "ACK-06"]
)
def test_actual_ingest_checkpoint_kill_reopen_and_ack_replay(tmp_path: Path, prefix: str) -> None:
    result = runner().run_backend_case(entry(prefix), observation(), tmp_path)
    assert result["result"] == "PASS"
    row = result["records"][0]
    assert row["termination_returncode"] == -signal.SIGKILL
    with pytest.raises(ChildProcessError):
        os.waitpid(row["pid"], os.WNOHANG)
    case = Path(row["case_directory"])
    actual = json.loads((case / "actual-state.json").read_text())
    committed = prefix in {"SQL-07", "ACK-06"}
    assert len(actual["tables"]["raw_commits"]) == int(committed)
    recovery = json.loads((case / "recovery.json").read_text())
    assert recovery["replay"]["ack"]["highest_contiguous_sequence"] == 1
    assert len(recovery["after"]["tables"]["raw_commits"]) == 1
    witness = json.loads((case / "boundary.json").read_text())
    assert witness["received_observation_hash"] == observation()["content_hash"]
    assert witness["transport_address"][0] == "127.0.0.1"
    assert row["input_sha256"] and row["actual_state_sha256"] and row["checkpoint_sha256"]
    assert row["comparison"] == "PASS"
    assert "expected" not in (case / "scenario.json").read_text()
    provenance = row["launch_provenance"]
    assert provenance["argv"][:3] == provenance["command_prefix"]
    assert provenance["command_prefix"][1:] == [
        "-I",
        str((ROOT / "tools/loopback_ack_crash_child.py").resolve()),
    ]
    for component in ("executable", "entrypoint"):
        assert (
            provenance[component]["sha256"]
            == hashlib.sha256(Path(provenance[component]["path"]).read_bytes()).hexdigest()
        )
    for name in ("reopen", "replay"):
        launch = json.loads((case / f"{name}-launch.json").read_text())
        assert launch["argv"][:3] == provenance["command_prefix"]
        assert launch["entrypoint"] == provenance["entrypoint"]


def test_wrong_expected_is_detected_after_real_execution(tmp_path: Path) -> None:
    case = copy.deepcopy(entry("SQL-07"))
    case["expected_post_restart_state"]["sql_row_deltas"]["raw_commits"] = 999999
    with pytest.raises(ValueError, match="E_RESTART_STATE_MISMATCH"):
        runner().run_backend_case(case, observation(), tmp_path)
    assert len(list(tmp_path.rglob("actual-state.json"))) == 1


@pytest.mark.parametrize(
    "table,column",
    [("raw_commits", "raw_observation_content_hash"), ("reducer_cursors", "cursor_hash")],
)
def test_copied_actual_store_mutation_is_detected(tmp_path: Path, table: str, column: str) -> None:
    result = runner().run_backend_case(entry("SQL-07"), observation(), tmp_path / "original")
    case = Path(result["records"][0]["case_directory"])
    database = next(case.rglob("run.sqlite3"))
    copied = tmp_path / "corrupt-copy" / database.parent.name
    shutil.copytree(database.parent, copied)
    corrupt_journal(RunStore(copied / "run.sqlite3"), table, column)
    with pytest.raises(ValueError, match="E_STORE_DURABLE_CHAIN"):
        read_restart_state(copied)
    assert read_restart_state(database.parent)["tables"]["raw_commits"]


def test_original_ids_stay_visible_without_full_qualification(tmp_path: Path) -> None:
    result = runner().run_loopback_ack_crash_matrix(PACK, tmp_path, observation_input=observation())
    assert result["result"] == "HOLD"
    assert len(result["records"]) == 7
    assert {row["status"] for row in result["records"]} == {"NOT_IMPLEMENTED"}
    assert sum(row.get("scoped_result") == "PASS" for row in result["records"]) == 2
    assert result["legacy_full_qualification"] == "HOLD"


def test_entire_inherited_inventory_remains_unqualified_without_executed_evidence(
    tmp_path: Path,
) -> None:
    entries = json.loads((PACK / "docs/registries/crash-harness-registry.v1.json").read_text())
    rows = []
    for family in {row["harness"] for row in entries["entries"]}:
        result = runner().run_family(PACK, tmp_path, family, None)
        assert result["result"] == "HOLD"
        rows.extend(result["records"])
    assert len(rows) == 46
    assert {row["vector_id"] for row in rows} == {row["vector_id"] for row in entries["entries"]}
    assert all(row["status"] == "NOT_IMPLEMENTED" for row in rows)
    assert not list(tmp_path.iterdir())from __future__ import annotations

import base64
import hashlib
import json
import subprocess
import sys
from dataclasses import replace
from pathlib import Path
from typing import Any

import pytest

from tools import run_command_registry


def test_source_identity_excludes_only_declared_compiler_dirt(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    changed = ["extension/dist/compiler.js"]
    monkeypatch.setattr(
        run_command_registry, "_declared_compiler_outputs", lambda root: set(changed)
    )
    source_dirty = False

    def git(argv: list[str], **kwargs: Any) -> Any:
        args = argv[3:]
        if args == ["rev-parse", "--show-toplevel"]:
            out = str(tmp_path)
        elif args == ["rev-parse", "HEAD"]:
            out = "a" * 40
        elif args == ["rev-parse", "HEAD^{tree}"]:
            out = "b" * 40
        elif args == ["diff", "--name-only"]:
            out = "\n".join(changed + (["src/unauthorized.py"] if source_dirty else []))
        elif args in (
            ["diff", "--cached", "--name-only"],
            ["ls-files", "--others", "--exclude-standard"],
        ):
            out = ""
        else:
            pytest.fail("An empty git diff pathspec would include compiler bytes")
        return subprocess.CompletedProcess(argv, 0, out, "")

    monkeypatch.setattr(subprocess, "run", git)
    expected = {"head": "a" * 40, "tree": "b" * 40, "source_diff": ""}
    assert run_command_registry._git_source_identity(tmp_path) == expected
    changed.append("extension/dist/second.js")
    assert run_command_registry._git_source_identity(tmp_path) == expected
    source_dirty = True
    with pytest.raises(ValueError, match="LOCAL_GIT"):
        run_command_registry._git_source_identity(tmp_path)


def test_phase_issue_candidate_and_retained_checks_reject_drift(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from tools import phase_evidence as phase
    from tools.full_verifier_config import load_controller_config
    from tools.retained_artifact_io import RetainedArtifactIO

    root = Path(__file__).resolve().parents[2]
    original = load_controller_config(
        root / "vendor/hybrid-discovery-v6.3.6/docs/configs/full-verifier-controller.v2.json"
    )
    spec = phase.contract(original)
    assert spec is not None
    config = replace(
        original,
        current_checkout_root=tmp_path / "runtime",
        governed_source_pack=tmp_path / "pack",
        evidence_root=tmp_path / "observed",
        candidate_command_evidence=tmp_path / "observed/candidate.json",
        descendant_repository_receipt=tmp_path / "descendant.json",
    )
    config.evidence_root.mkdir()
    source: dict[str, object] = {"head": "a" * 40, "tree": "b" * 40, "source_diff": ""}
    monkeypatch.setattr(run_command_registry, "_git_source_identity", lambda root: source.copy())
    docs = config.governed_source_pack / "docs"
    paths = [
        "tasks/task-manifest.v6.3.6.json",
        "registries/artifact-ownership.v1.json",
        "schemas/artifact-ownership.schema.json",
        *[
            "registries/" + n
            for n in (
                "task-command-registry.v1.json",
                "review-command-registry.v1.json",
                "cybersecurity-command-registry.v1.json",
                "baseline-replay-command-registry.v1.json",
            )
        ],
    ]
    for name in paths:
        path = docs / name
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text("{}")
    contract_path = config.governed_source_pack / phase.CONTRACT
    contract_path.parent.mkdir(parents=True)
    contract_path.write_text(json.dumps(spec))
    identifiers = sorted({i for row in spec["phases"].values() for i in row})
    # Registered synthetic commands read finite expected input files. Actual stdout
    # is captured by the same runner used in the campaign, never copied from oracle.
    registered = [
        {
            "command_id": i,
            "argv": [
                sys.executable,
                "-c",
                "from pathlib import Path; import sys; print(Path(sys.argv[1]).read_text())",
                str(tmp_path / (i + ".input")),
            ],
            "cwd": str(tmp_path),
            "expected_exit": 0,
        }
        for i in identifiers
    ]
    (docs / paths[3]).write_text(json.dumps({"commands": registered}))
    inputs = {name: hashlib.sha256((docs / name).read_bytes()).hexdigest() for name in paths}
    observed = []
    for command in registered:
        identifier = command["command_id"]
        payload: Any = "TEST_ONLY_OBSERVATION"
        if identifier in phase.CURRENT_COMMANDS:
            payload = {
                "gate": "CURRENT_DECLARATION_VALID"
                if identifier == "VALIDATE_CURRENT_DECLARATION"
                else "CURRENT_DESCENDANT_SOURCE_VALID",
                "result": "PASS",
                "production_authority": "NONE",
                "source_identity": source,
                "contract_sha256": hashlib.sha256(contract_path.read_bytes()).hexdigest(),
                "input_hashes": inputs,
                "adopted_source": spec["adopted_source"],
                "historical_receipt_sha256": spec["historical_migration_sha256"],
                "historical_regressions": {"exit_code": 0},
                "historical_acceptance": "NOT_INFERRED",
            }
        (tmp_path / (identifier + ".input")).write_text(json.dumps(payload))
        observed.append(
            run_command_registry.evaluate_invocation(
                command,
                environment={},
                working_directory=tmp_path,
                log_directory=config.evidence_root / "command-logs",
            )
        )
    extras = [r for r in observed if r["command_id"] in phase.CURRENT_COMMANDS]
    candidate = {
        "controller_binding": config.binding(),
        "results": [r for r in observed if r not in extras],
    }
    config.candidate_command_evidence.write_text(json.dumps(candidate))
    with pytest.raises(ValueError, match="E_PHASE_EVIDENCE"):
        phase.issue_phases(config, extras[:-1], source.copy())
    original_identity = source.copy()
    source["head"] = "c" * 40
    with pytest.raises(ValueError, match="E_PHASE_SOURCE_DRIFT"):
        phase.issue_phases(config, extras, original_identity)
    source.update(original_identity)
    phase.issue_phases(config, extras, original_identity)
    proofs = [
        json.loads((config.evidence_root / (task + ".json")).read_bytes())
        for task in spec["phases"]
    ]
    for proof in proofs:
        phase.verify_phase(proof, config)
    with pytest.raises(ValueError, match="E_PHASE_EVIDENCE"):
        phase.verify_phase({**proofs[0], "commands": []}, config)
    assert config.descendant_repository_receipt is not None
    config.descendant_repository_receipt.write_text(
        json.dumps({"repository_commit": source["head"], "repository_tree": source["tree"]})
    )
    retained = tmp_path / "retained"
    retained.mkdir()
    records = []
    for index, path in enumerate(
        [contract_path, *(docs / n for n in paths), config.descendant_repository_receipt]
    ):
        raw = path.read_bytes()
        name = str(index)
        (retained / name).write_bytes(raw)
        records.append(
            {
                "recorded_locator": str(path),
                "recorded_boundary": str(tmp_path),
                "copied_relative_path": name,
                "size_bytes": len(raw),
                "sha256": hashlib.sha256(raw).hexdigest(),
            }
        )
        path.unlink()
    artifacts = RetainedArtifactIO.from_manifest(
        {
            "schema_version": "retained-artifact-manifest/v1",
            "recorded_boundaries": [str(tmp_path)],
            "files": records,
        },
        retained,
    )
    source["head"] = "d" * 40  # Originals gone and live HEAD changed; retained proof remains bound.
    for proof in proofs:
        phase.verify_phase(proof, config, artifacts)
    (retained / "0").write_text("tamper")
    with pytest.raises(ValueError, match="E_RETAINED_ARTIFACT"):
        phase.verify_phase(proofs[0], config, artifacts)


