        observed["cim"]["CreationDate"] = {
            "null": None,
            "empty": "",
            "malformed": "/Date(not-a-timestamp)/",
            "overflow": "/Date(99999999999999999999999999999999999999)/",
        }[damage]
    observed["cim_raw"] = json.dumps(observed["cim"])
