            result_sha256=sha256(rfc8785.dumps(review)).hexdigest(),
            now=NOW,
        )
        reviews.append(review)
        launches.append(launch)
        receipts.append(receipt)
    return {"private": private, "reviews": reviews, "launches": launches, "receipts": receipts}


