import pytest
from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PrivateKey

from moj_discovery.review_authorization import (
    sign_review_launch_authorization,
    verify_review_launch_authorization,
)

NOW = datetime(2030, 1, 1, tzinfo=UTC)
WORKSPACE = "/home/thenam176/betting-helper/review-workspaces/hybrid-discovery-v6.3.6/review-a"
PACK_SHA256 = "a" * 64
BOOT_ID = "00000000-0000-0000-0000-000000000000"


def _launch(
    private: Ed25519PrivateKey,
    *,
    boot_id: str = BOOT_ID,
    audience: str = "hybrid-discovery:independent-review-launcher:v1",
    review_role: str = "IMPLEMENTATION_READINESS_REVIEWER",
    trust_epoch: int = 0,
    issued_at: datetime = NOW,
    not_before: datetime = NOW,
    expires_at: datetime = NOW + timedelta(seconds=14400),
) -> dict[str, object]:
    return sign_review_launch_authorization(
        {
            "schema_version": "review-launch-authorization/v1",
            "issuer_role": "HOST_REVIEW_AUTHORITY",
            "audience": audience,
            "review_role": review_role,
            "review_run_id": "11111111-1111-4111-8111-111111111111",
            "pack_zip_sha256": PACK_SHA256,
            "pack_manifest_sha256": "b" * 64,
            "repo0_receipt_sha256": "c" * 64,
            "repo0_commit_oid": "d" * 40,
            "repo0_tree_oid": "e" * 40,
            "repo0_file_tree_root_sha256": "f" * 64,
            "workspace_root": WORKSPACE,
            "input_mounts": [
                {
                    "source_root": f"/sealed/input-{index}",
                    "workspace_mount": f"/sealed/input-{index}",
                    "mode": "READ_ONLY",
                    "content_root_sha256": sha256(f"input-{index}".encode()).hexdigest(),
                }
                for index in range(5)
            ],
            "excluded_roots": ["/authoring", "/peer"],
            "allowed_output_root": (
                "/home/thenam176/betting-helper/reviews/hybrid-discovery-v6.3.6/review-a"
            ),
            "prompt_sha256": "1" * 64,
            "command_registry_sha256": "2" * 64,
            "issued_at": issued_at.isoformat(),
            "not_before": not_before.isoformat(),
            "expires_at": expires_at.isoformat(),
            "maximum_duration_seconds": 14400,
            "one_use_serial": "3" * 32,
            "nonce": "A" * 43,
            "fresh_session_required": True,
            "production_authority": "NONE",
            "signature_algorithm": "Ed25519",
            "host_boot_id": boot_id,
            "trust_epoch": trust_epoch,
        },
        private,
    )


def test_security_boundary() -> None:
    vectors = {
        "allow": "SEC_AUTHORIZATION_TRUST-ALLOW",
        "deny": "SEC_AUTHORIZATION_TRUST-DENY",
        "mutate": "SEC_AUTHORIZATION_TRUST-MUTATE",
    }
    private = Ed25519PrivateKey.generate()
    launch = _launch(private)
    assert (
        verify_review_launch_authorization(
            launch,
            private.public_key(),
            "IMPLEMENTATION_READINESS_REVIEWER",
            WORKSPACE,
            PACK_SHA256,
            expected_host_boot_id=BOOT_ID,
            expected_trust_epoch=0,
            now=NOW,
        )["result"]
        == "PASS"
    ), vectors["allow"]

    with pytest.raises(ValueError):
        verify_review_launch_authorization(
            _launch(private, boot_id="10000000-0000-0000-0000-000000000000"),
            private.public_key(),
            "IMPLEMENTATION_READINESS_REVIEWER",
            WORKSPACE,
            PACK_SHA256,
            expected_host_boot_id=BOOT_ID,
            expected_trust_epoch=0,
            now=NOW,
        )
    for changed, kwargs in (
        (_launch(private, review_role="CYBERSECURITY_REVIEWER"), {}),
        (_launch(private, audience="hybrid-discovery:wrong:v1"), {}),
        (_launch(private, trust_epoch=1), {}),
    ):
        with pytest.raises(ValueError):
            verify_review_launch_authorization(
                changed,
                private.public_key(),
                "IMPLEMENTATION_READINESS_REVIEWER",
                WORKSPACE,
                PACK_SHA256,
                expected_host_boot_id=BOOT_ID,
                expected_trust_epoch=0,
                now=NOW,
                **kwargs,
            )
    mutated = dict(launch)
    mutated["audience"] = "hybrid-discovery:mutated:v1"
    with pytest.raises(ValueError):
        verify_review_launch_authorization(
            mutated,
            private.public_key(),
            "IMPLEMENTATION_READINESS_REVIEWER",
            WORKSPACE,
            PACK_SHA256,
            expected_host_boot_id=BOOT_ID,
            expected_trust_epoch=0,
            now=NOW,
        )
    assert vectors["deny"] and vectors["mutate"]
    with pytest.raises(ValueError):
        verify_review_launch_authorization(
            launch,
            Ed25519PrivateKey.generate().public_key(),
            "IMPLEMENTATION_READINESS_REVIEWER",
            WORKSPACE,
            PACK_SHA256,
            now=NOW,
        )import json
import os
import subprocess
from pathlib import Path
from tempfile import TemporaryDirectory

import pytest

from tools.prepare_review_workspace import build_bubblewrap_argv


def _mount(source: Path) -> dict[str, str]:
    return {"source_root": str(source), "workspace_mount": str(source), "mode": "READ_ONLY"}


def test_security_boundary() -> None:
    # /tmp is replaced by the generated namespace; keep its inputs outside it.
    with TemporaryDirectory(prefix="TEST_ONLY-isolation-", dir=Path.home()) as directory:
        _check_generated_boundary(Path(directory))


def _check_generated_boundary(tmp_path: Path) -> None:
    vectors = {
        "allow": "SEC_BUBBLEWRAP_ISOLATION-ALLOW",
        "deny": "SEC_BUBBLEWRAP_ISOLATION-DENY",
        "mutate": "SEC_BUBBLEWRAP_ISOLATION-MUTATE",
    }
    scratch = tmp_path / "workspace/scratch"
    output = tmp_path / "output"
    runtime = tmp_path / "runtime"
    pack = tmp_path / "pack"
    scratch.mkdir(parents=True)
    output.mkdir()
    for name in ("control", "home", "tmp"):
        (scratch / name).mkdir()
    runtime.mkdir()
    pack.mkdir()
    for path in (tmp_path / "seal.json", tmp_path / "pack.zip", tmp_path / "pack.zip.sha256"):
        path.write_text(path.name)
    python_dependencies = scratch / "node-project/node_modules"
    node_dependencies = scratch / "node-project/extension/node_modules"
    python_dependencies.mkdir(parents=True)
    node_dependencies.mkdir(parents=True)
    config: dict[str, object] = {
        "environment": {"UV_OFFLINE": "1"},
        "excluded_roots": [str(tmp_path / "authoring"), str(tmp_path / "peer")],
        "input_mounts": [
            _mount(pack),
            _mount(runtime),
            _mount(tmp_path / "seal.json"),
            _mount(tmp_path / "pack.zip"),
            _mount(tmp_path / "pack.zip.sha256"),
        ],
        "node_environment": {
            "dependency_mounts": [_mount(python_dependencies), _mount(node_dependencies)]
        },
        "scratch_root": str(scratch),
        "output_root": str(output),
    }
    argv = build_bubblewrap_argv(config, {"argv": ["python", "-c", "pass"], "cwd": str(runtime)})
    assert {"--unshare-user", "--unshare-pid", "--unshare-net", "--unshare-uts"} <= set(argv)
    assert str(tmp_path / "authoring") not in argv
    assert str(tmp_path / "peer") not in argv
    pairs = [argv[index : index + 2] for index in range(len(argv) - 1)]
    assert "--die-with-parent" not in argv
    assert [str(scratch), str(scratch)] not in pairs
    assert [str(scratch / "tmp"), str(Path("/") / "tmp")] in pairs

    unsafe = dict(config)
    unsafe["input_mounts"] = [{**_mount(pack), "mode": "READ_WRITE"}]
    with pytest.raises(ValueError, match="E_REVIEW_WORKSPACE_ISOLATION"):
        build_bubblewrap_argv(unsafe, {"argv": ["python"], "cwd": str(runtime)})

    # Only synthetic sentinels: never inspect a real key, state or peer output.
    excluded = tmp_path / "TEST_ONLY-host"
    excluded.mkdir()
    sentinels = [excluded / name for name in ("authoring", "peer", "key", "state")]
    for path in sentinels:
        path.write_text("TEST_ONLY")
    script = """
import json, os, sys
from pathlib import Path
runtime, output, *sentinels = map(Path, sys.argv[1:])
observed = {
    'net': os.readlink('/proc/self/ns/net'),
    'visible': [p.exists() for p in sentinels],
    'proc_escape': [Path('/proc/1/root' + str(p)).exists() for p in sentinels],
}
(output / 'allowed').write_text('TEST_ONLY')
observed['output'] = (output / 'allowed').read_text()
try:
    (runtime / 'escape-probe').write_text('TEST_ONLY')
    observed['write_errno'] = 0
except OSError as error:
    observed['write_errno'] = error.errno
print(json.dumps(observed))
"""
    command = {"argv": ["/usr/bin/python3", "-c", script, str(runtime), str(output),
                        *map(str, sentinels)], "cwd": str(runtime)}
    generated = build_bubblewrap_argv(config, command)

    def observe(arguments: list[str]) -> dict[str, object]:
        completed = subprocess.run(  # noqa: S603 -- generated boundary, owned synthetic inputs.
            arguments, check=False, capture_output=True, text=True, timeout=15,
        )
        assert completed.returncode == 0, completed.stderr
        return json.loads(completed.stdout)  # type: ignore[no-any-return]

    observed = observe(generated)
    assert observed["net"] != os.readlink("/proc/self/ns/net"), vectors["allow"]
    assert observed["visible"] == observed["proc_escape"] == [False] * len(sentinels), (
        vectors["deny"]
    )
    assert observed["write_errno"] == 30  # EROFS from the actual readonly mount.
    assert observed["output"] == "TEST_ONLY"
    assert not (runtime / "escape-probe").exists()

    # Each mutation must change the corresponding observed boundary result.
    shared_network = [arg for arg in generated if arg != "--unshare-net"]
    assert observe(shared_network)["net"] == os.readlink("/proc/self/ns/net")
    writable_runtime = generated.copy()
    index = next(i for i in range(len(generated) - 2)
                 if generated[i:i + 3] == ["--ro-bind", str(runtime), str(runtime)])
    writable_runtime[index] = "--bind"
    assert observe(writable_runtime)["write_errno"] == 0
    assert (runtime / "escape-probe").read_text() == "TEST_ONLY"
    (runtime / "escape-probe").unlink()
    escaped = generated.copy()
    index = escaped.index("--")
    escaped[index:index] = ["--ro-bind", str(excluded), str(excluded)]
    assert observe(escaped)["visible"] == [True] * len(sentinels), vectors["mutate"]import json
import shutil
import subprocess
from pathlib import Path

import pytest

from moj_discovery.canonical import (
    CanonicalError,
    canonical_content_hash,
    parse_strict_json,
    verify_canonical_content_hash,
)

ROOT = Path(__file__).parents[2]


def test_security_boundary() -> None:
    vectors_by_kind = {
        "allow": "SEC_CANONICAL_HASHING-ALLOW",
        "deny": "SEC_CANONICAL_HASHING-DENY",
        "mutate": "SEC_CANONICAL_HASHING-MUTATE",
    }
    vectors = json.loads(
        (ROOT / "vendor/hybrid-discovery-v6.3.6/vectors/canonical-hashing-v1.json").read_text()
    )
    vector = next(item for item in vectors["valid_vectors"] if item["vector_id"] == "CANON-ASCII")
    value = parse_strict_json(b'{"b":"2","a":"alpha"}')
    assert value == vector["input"]
    python_hash = canonical_content_hash(str(vector["artifact_type"]), value)
    assert python_hash == vector["sha256"], vectors_by_kind["allow"]
    script = """
import {readFileSync} from 'node:fs';
import {canonicalContentHash,verifyCanonicalContentHash} from './extension/dist/canonical.js';
const registryPath='./vendor/hybrid-discovery-v6.3.6/registries/canonical-hash-domains.v1.json';
const registry=JSON.parse(readFileSync(registryPath,'utf8'));
const value=JSON.parse(process.argv[1]);
const digest=await canonicalContentHash(process.argv[2],value,registry);
await verifyCanonicalContentHash(process.argv[2],value,digest,registry);
try {
  await verifyCanonicalContentHash(process.argv[2],value,'0'.repeat(64),registry);
  process.exit(9);
} catch (error) {
  if (!(error instanceof Error) || error.message !== 'CONTENT_HASH_MISMATCH') throw error;
}
process.stdout.write(digest);
"""
    node = shutil.which("node")
    assert node is not None
    node_hash = subprocess.run(  # noqa: S603 -- fixed script and validated vector input
        [
            node,
            "--input-type=module",
            "--eval",
            script,
            json.dumps(value),
            str(vector["artifact_type"]),
        ],
        check=True,
        capture_output=True,
        text=True,
    ).stdout
    assert node_hash == python_hash, vectors_by_kind["allow"]
    changed = canonical_content_hash(str(vector["artifact_type"]), {"a": "altered", "b": "2"})
    assert changed != vector["sha256"], vectors_by_kind["mutate"]
    assert verify_canonical_content_hash(str(vector["artifact_type"]), value, str(vector["sha256"]))
    with pytest.raises(CanonicalError, match="CONTENT_HASH_MISMATCH"):
        verify_canonical_content_hash(str(vector["artifact_type"]), value, "0" * 64)
    with pytest.raises(CanonicalError, match="DUPLICATE_JSON_KEY"):
        parse_strict_json(b'{"a":1,"a":2}')
    assert vectors_by_kind["deny"]import json
